CREATE INDEX catalog_digest ON handdraw.premium_catalog(sha256);
GRANT SELECT ON handdraw.premium_catalog TO handdraw_access_owner;
CREATE TABLE handdraw.assets(
 id text COLLATE "C" PRIMARY KEY CHECK(handdraw.valid_resource_id(id,'ast')),
 workspace_id text COLLATE "C" NOT NULL REFERENCES handdraw.workspaces(id),
 board_id text COLLATE "C" NOT NULL,
 uploaded_by text COLLATE "C" NOT NULL REFERENCES handdraw.profiles(id),
 purpose text NOT NULL CHECK(purpose IN ('attachment','import_source')),
 status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','available','deleting','deleted')),
 size_bytes bigint NOT NULL CHECK(size_bytes>0 AND size_bytes<=64000000),
 mime_type text NOT NULL,
 sha256 text NOT NULL CHECK(sha256 ~ '^[0-9a-f]{64}$'),
 premium boolean NOT NULL DEFAULT false,
 accounted boolean NOT NULL DEFAULT false,
 expires_at timestamptz NOT NULL DEFAULT clock_timestamp()+interval '15 minutes',
 created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 UNIQUE(workspace_id,board_id,id),
 CHECK(purpose<>'attachment' OR size_bytes<=20000000),
 CHECK(NOT accounted OR purpose='attachment')
);
-- Asset rows deliberately outlive their board until object deletion is verified.
CREATE INDEX asset_board ON handdraw.assets(board_id,status);
CREATE INDEX asset_expiry ON handdraw.assets(expires_at) WHERE status IN ('pending','deleting');
ALTER TABLE handdraw.assets ENABLE ROW LEVEL SECURITY;
ALTER TABLE handdraw.assets FORCE ROW LEVEL SECURITY;
CREATE POLICY migration_assets ON handdraw.assets TO CURRENT_USER USING(true) WITH CHECK(true);
CREATE POLICY access_assets ON handdraw.assets TO handdraw_access_owner USING(true) WITH CHECK(true);
CREATE POLICY read_assets ON handdraw.assets FOR SELECT TO handdraw_request USING(handdraw.board_content_readable(board_id) AND (purpose='attachment' OR uploaded_by=handdraw.current_actor() OR handdraw.is_workspace_owner(workspace_id)));
GRANT SELECT ON handdraw.assets TO handdraw_request;
GRANT SELECT,INSERT,UPDATE,DELETE ON handdraw.assets TO handdraw_access_owner;
CREATE FUNCTION handdraw.lock_asset(a text,writing boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE r handdraw.assets%ROWTYPE;
BEGIN
 SELECT * INTO r FROM handdraw.assets WHERE id=a;
 IF NOT FOUND OR NOT handdraw.board_content_readable(r.board_id) OR (r.purpose<>'attachment' AND r.uploaded_by<>handdraw.current_actor() AND NOT handdraw.is_workspace_owner(r.workspace_id)) THEN RAISE EXCEPTION 'not found' USING ERRCODE='HD404'; END IF;
 PERFORM 1 FROM handdraw.workspaces WHERE id=r.workspace_id FOR UPDATE;
 IF NOT handdraw.board_content_readable(r.board_id) THEN RAISE EXCEPTION 'not found' USING ERRCODE='HD404'; END IF;
 IF writing AND (NOT handdraw.can_write_workspace(r.workspace_id) OR r.uploaded_by<>handdraw.current_actor()) THEN RAISE EXCEPTION 'denied' USING ERRCODE='HD403'; END IF;
END; $$;
CREATE FUNCTION handdraw.reserve_asset(a text,b text,p text,n bigint,mime text,digest text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE w text;capacity bigint;premium boolean;
BEGIN
 SELECT workspace_id INTO w FROM handdraw.boards WHERE id=b AND status='active' AND deleted_at IS NULL;
 IF w IS NULL OR NOT handdraw.lock_content_workspace(w) THEN RAISE EXCEPTION 'denied' USING ERRCODE='HD403'; END IF;
 IF NOT EXISTS(SELECT 1 FROM handdraw.boards WHERE id=b AND status='active' AND deleted_at IS NULL) THEN RAISE EXCEPTION 'not found' USING ERRCODE='HD404'; END IF;
 SELECT EXISTS(SELECT 1 FROM handdraw.premium_catalog c WHERE c.sha256=digest) INTO premium;
 IF premium AND NOT(handdraw.has_personal_premium() OR EXISTS(SELECT 1 FROM handdraw.workspaces WHERE id=w AND kind='team')) THEN RAISE EXCEPTION 'premium denied' USING ERRCODE='HD403'; END IF;
 SELECT quota_bytes INTO capacity FROM handdraw.access_entitlement(w);
 UPDATE handdraw.workspace_usage SET reserved_bytes=reserved_bytes+n,revision=revision+1,updated_at=clock_timestamp() WHERE workspace_id=w AND n>0 AND used_bytes+reserved_bytes+n<=capacity;
 IF NOT FOUND THEN RAISE EXCEPTION 'quota exceeded' USING ERRCODE='HD413'; END IF;
 INSERT INTO handdraw.assets(id,workspace_id,board_id,uploaded_by,purpose,size_bytes,mime_type,sha256,premium) VALUES(a,w,b,handdraw.current_actor(),p,n,mime,digest,premium);
END; $$;
CREATE FUNCTION handdraw.complete_asset(a text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE r handdraw.assets%ROWTYPE;
BEGIN
 PERFORM handdraw.lock_asset(a,true);
 SELECT * INTO r FROM handdraw.assets WHERE id=a FOR UPDATE;
 IF r.status='available' THEN RETURN; END IF;
 IF r.status<>'pending' OR r.expires_at<=clock_timestamp() THEN RAISE EXCEPTION 'expired upload' USING ERRCODE='HD409'; END IF;
 IF r.premium AND NOT(handdraw.has_personal_premium() OR EXISTS(SELECT 1 FROM handdraw.workspaces WHERE id=r.workspace_id AND kind='team')) THEN RAISE EXCEPTION 'premium denied' USING ERRCODE='HD403'; END IF;
 UPDATE handdraw.assets SET status='available',accounted=(purpose='attachment') WHERE id=a;
 IF r.purpose='attachment' THEN UPDATE handdraw.workspace_usage SET reserved_bytes=reserved_bytes-r.size_bytes,used_bytes=used_bytes+r.size_bytes,revision=revision+1,updated_at=clock_timestamp() WHERE workspace_id=r.workspace_id; END IF;
END; $$;
CREATE FUNCTION handdraw.asset_cleanup_candidate() RETURNS SETOF handdraw.assets LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE r handdraw.assets%ROWTYPE;
BEGIN
 SELECT a.* INTO r FROM handdraw.assets a WHERE a.status<>'deleted' AND (NOT EXISTS(SELECT 1 FROM handdraw.boards b WHERE b.id=a.board_id AND b.status<>'deleting') OR (a.expires_at<=clock_timestamp() AND (a.status='pending' OR a.purpose='import_source')) OR a.status='deleting') ORDER BY a.expires_at,a.id LIMIT 1;
 IF NOT FOUND THEN RETURN; END IF;
 -- The caller keeps this transaction open across bounded local object removal.
 PERFORM 1 FROM handdraw.workspaces WHERE id=r.workspace_id FOR UPDATE SKIP LOCKED;
 IF NOT FOUND THEN RETURN; END IF;
 SELECT * INTO r FROM handdraw.assets WHERE id=r.id AND status<>'deleted' FOR UPDATE;
 IF NOT FOUND THEN RETURN; END IF;
 IF EXISTS(SELECT 1 FROM handdraw.boards b WHERE b.id=r.board_id AND b.status<>'deleting') AND r.status<>'deleting' AND NOT(r.expires_at<=clock_timestamp() AND (r.status='pending' OR r.purpose='import_source')) THEN RETURN; END IF;
 UPDATE handdraw.assets SET status='deleting' WHERE id=r.id;
 RETURN NEXT r;
END; $$;
CREATE FUNCTION handdraw.finish_asset_cleanup(a text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE r handdraw.assets%ROWTYPE;
BEGIN
 SELECT * INTO r FROM handdraw.assets WHERE id=a;
 IF NOT FOUND OR r.status='deleted' THEN RETURN; END IF;
 PERFORM 1 FROM handdraw.workspaces WHERE id=r.workspace_id FOR UPDATE;
 SELECT * INTO r FROM handdraw.assets WHERE id=a FOR UPDATE;
 IF r.status<>'deleting' THEN RAISE EXCEPTION 'invalid cleanup' USING ERRCODE='HD409'; END IF;
 UPDATE handdraw.workspace_usage SET used_bytes=used_bytes-CASE WHEN r.accounted THEN r.size_bytes ELSE 0 END,reserved_bytes=reserved_bytes-CASE WHEN r.accounted THEN 0 ELSE r.size_bytes END,revision=revision+1,updated_at=clock_timestamp() WHERE workspace_id=r.workspace_id;
 UPDATE handdraw.assets SET status='deleted',accounted=false WHERE id=a;
END; $$;
GRANT CREATE ON SCHEMA handdraw TO handdraw_access_owner;
ALTER FUNCTION handdraw.lock_asset(text,boolean) OWNER TO handdraw_access_owner;
ALTER FUNCTION handdraw.reserve_asset(text,text,text,bigint,text,text) OWNER TO handdraw_access_owner;
ALTER FUNCTION handdraw.complete_asset(text) OWNER TO handdraw_access_owner;
ALTER FUNCTION handdraw.asset_cleanup_candidate() OWNER TO handdraw_access_owner;
ALTER FUNCTION handdraw.finish_asset_cleanup(text) OWNER TO handdraw_access_owner;
REVOKE CREATE ON SCHEMA handdraw FROM handdraw_access_owner;
REVOKE ALL ON FUNCTION handdraw.lock_asset(text,boolean),handdraw.reserve_asset(text,text,text,bigint,text,text),handdraw.complete_asset(text),handdraw.asset_cleanup_candidate(),handdraw.finish_asset_cleanup(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION handdraw.lock_asset(text,boolean),handdraw.reserve_asset(text,text,text,bigint,text,text),handdraw.complete_asset(text) TO handdraw_request;
GRANT EXECUTE ON FUNCTION handdraw.asset_cleanup_candidate(),handdraw.finish_asset_cleanup(text) TO handdraw_cleanup_worker;
COMMIT;
